#include <cstdio>
#include <queue>
#include <iostream>

using namespace std;

const int N = 2e5 + 5;
const int E = N << 1;
const long long oo = 1e18;

int n, m, s, q;
int h[N], to[E], nx[E], wt[E], et;
int vis[N];
long long d[N];
priority_queue <pair<long long, int>> pq;

void ae(int u, int v, int w) {
    et++;
    to[et] = v;
    nx[et] = h[u];
    wt[et] = w;
    h[u] = et;
}

int main() {
    scanf("%d%d%d%d", &n, &m, &s, &q);
    for (int i = 1; i <= m; i++) {
        int u, v, l;
        scanf("%d%d%d", &u, &v, &l);
        ae(u, v, l);
        ae(v, u, l);
    }
    for (int i = 1; i <= n; i++)
        d[i] = oo;
    d[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto p = pq.top();
        pq.pop();
        int u = p.second;
        if (vis[u])
            continue;
        vis[u] = 1;
        for (int i = h[u]; i; i = nx[i])
            if (d[u] + wt[i] < d[to[i]]) {
                d[to[i]] = d[u] + wt[i];
                pq.push({-d[to[i]], to[i]});
            }
    }
    while (q--) {
        int p;
        scanf("%d", &p);
        printf("%lld\n", d[p]);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e6+10;
int n, k;
vector<int> e[N];
int f[N][25], dep[N], g[N], h[N];

void dfs(int u, int fa){
    dep[u] = dep[fa] + 1;
    f[u][0] = fa;
    for(int i = 1; i <= 20; i++){
        f[u][i] = f[f[u][i - 1]][i - 1];
    }
    for(auto v: e[u]){
        if(v == fa) continue;
        dfs(v, u);
    }
}

int lca(int u, int v){
    if(dep[u] < dep[v]) swap(u, v);
    int t = dep[u] - dep[v];
    for(int i = 0; i <= 20; i++){
        if(t & (1 << i)) u = f[u][i];
    }
    for(int i = 20; i >= 0; i--){
        if(f[u][i] != f[v][i])
            u = f[u][i], v = f[v][i];
    }
    if(u == v) return u;
    return f[u][0];
}

int ans;

void dfs2(int u, int fa){
    for(auto v: e[u]){
        if(v == fa) continue;
        dfs2(v, u);
        g[u] += g[v];
        h[u] += h[v];
    }
    if(!g[u] && h[u]) {
        ans++;
    }
}

void solve(){
    cin >> n >> k;
    for(int i = 1; i < n; i++){
        int u, v;
        cin >> u >> v;
        e[u].push_back(v);
        e[v].push_back(u);
    }
    dfs(1, 0);
    for(int i = 1; i <= k; i++){
        int u, v;
        cin >> u >> v;
        int lc = lca(u, v);
        g[u]++, g[v]++, g[lc]--, g[f[lc][0]]--;
    }
    int u, v;
    cin >> u >> v;
    int lc = lca(u, v);
    h[u]++, h[v]++, h[lc]--, h[f[lc][0]]--;
    dfs2(1, 0);
    cout << ans << '\n';
}

int main(){
    solve();
}
